do $release$ declare payload jsonb:='{"batch":"nl-scale-20261102-023","project":"hlvujbrmfdlrfxdjwsmb","actions":[{"ref":"d0","relation":"catalog_work_descriptions","key":{"work_id":987122001,"language":"nl"},"before":null,"after":{"work_id":987122001,"language":"nl","bound_author_id":987322001,"text":"Raynor Winn vertelt hoe zij en haar man Moth na het verlies van hun huis en zorgelijk nieuws over zijn gezondheid besluiten langs de Engelse kust te wandelen. Met weinig middelen volgen ze het South West Coast Path. De tocht brengt lichamelijke belasting, onzekerheid en ontmoetingen met onbekenden. Winn beschrijft hoe het landschap hun dagelijks bestaan gaat bepalen. Het boek is haar persoonlijke relaas over verlies, samen verdergaan en de zoektocht naar houvast buiten een vertrouwde woonplek.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.uitgeverijbalans.nl/boeken/het-zoutpad/","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p431096511","http://data.bibliotheken.nl/id/nbt/p433740027"],"checked_at":"2026-11-02T22:05:23.248Z","reference":"work:1461","note":"Primary Balans explicitly lists exact Dutch paperback9789463821513; KB agrees. Preserve verified book/translation identity. Summary is attributed to Winn as her personal memoir, not independent certification of medical or biographical claims. Do not substitute publisher current filmprint or ebook ISBNs.","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-015.json","sources":["https://www.uitgeverijbalans.nl/boeken/het-zoutpad/","https://openlibrary.org/works/OL20153160W","https://data.bibliotheken.nl/id/nbt/p431096511","https://data.bibliotheken.nl/id/nbt/p433740027"]},{"type":"cover_front_review","cover_id":12667409,"sha256":"c8c3fba14a538bb15323193667e5051e4e9c43496ad5bdfd7cb7b0551ffc6463","reference":"cover-semantic-review-002.json","li